import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matmul(torch::Tensor A, torch::Tensor B);
"""

matmul_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Tiled GEMM: C = A * B, all row-major [N, N] float32
// Each CTA computes a 128x128 tile of C with 256 threads,
// staging 128x8 A-tiles and 8x128 B-tiles in shared memory.
__global__ static void matmul_kernel(
    int M, int N, int K,
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C)
{
  // Global tensors (row-major)
  Tensor mA = make_tensor(make_gmem_ptr(A),
                          make_shape(M, K),
                          make_stride(K, Int<1>{}));   // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B),
                          make_shape(N, K),
                          make_stride(Int<1>{}, N));   // (N,K) view of B^T
  Tensor mC = make_tensor(make_gmem_ptr(C),
                          make_shape(M, N),
                          make_stride(N, Int<1>{}));   // (M,N)

  // CTA tiling
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<8>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,  X, _1>{}); // (128,8,k)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<  X,_1, _1>{}); // (128,8,k)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,  X>{});  // (128,128)

  // Shared memory
  __shared__ float smemA[128 * 8];
  __shared__ float smemB[128 * 8];
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<128>{}, Int<8>{}));
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<128>{}, Int<8>{}));

  // Thread layouts for global->shared copies (256 threads)
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));  // covers (128,8) with 4 rows/thread
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  // Thread layout for compute: 16x16 threads, each handles 8x8 outputs
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  Tensor tAgA = local_partition(gA, tA, threadIdx.x);  // (4,1,k)
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);  // (4,1)
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);  // (4,1,k)
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);  // (4,1)

  // Register fragments for the MMA-free (FMA) gemm
  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1,  X>{}); // (8,8k)
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step<  X,_1>{}); // (8,8k)
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});  // (8,8)

  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);

  int k_tile_max = size<2>(tAgA);
  for (int k_tile = 0; k_tile < k_tile_max; ++k_tile) {
    // Stage tiles in shared memory
    copy(tAgA(_, _, k_tile), tAsA);
    copy(tBgB(_, _, k_tile), tBsB);
    __syncthreads();

    // Compute rank-k updates from shared memory
    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }

  // Epilogue: write accumulators to global memory
  copy(tCrC, tCgC);
}

torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "A and B must be float32");

  int64_t M = A.size(0);
  int64_t K = A.size(1);
  int64_t N = B.size(1);
  TORCH_CHECK(B.size(0) == K, "Inner dimensions must match");
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 8 == 0,
              "Dimensions must be multiples of the tile sizes (M,N % 128, K % 8)");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::empty({M, N}, A.options());

  dim3 block(256);
  dim3 grid((unsigned)(M / 128), (unsigned)(N / 128));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  matmul_kernel<<<grid, block, 0, stream>>>(
      (int)M, (int)N, (int)K,
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>());

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE matmul launch failed: ",
              cudaGetErrorString(err));

  return C;
}
"""

cute_matmul_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=matmul_cpp_decl,
    cuda_sources=matmul_cuda_src,
    functions=["matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--expt-relaxed-constexpr"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using a custom tiled CUTE/CUDA GEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matmul(A, B)

